# Calculate N for L=3 using standard Cantor pairing function
# Pairs (x, y) where 0 <= x, y < 3
# f(x, y) = ((x+y)(x+y+1) // 2) + x
N = 0
for x in range(3):
    for y in range(3):
        f_xy = ((x + y) * (x + y + 1) // 2) + x
        if f_xy % 2 != 0:
            N += 1
print(f"N for 3x3 standard enumeration: {N}")
